import itertools

import ale_py
import gymnasium as gym


gym.register_envs(ale_py)


def build_state(ram, previous_state=None):
    ball_x = int(ram[49])
    ball_y = int(ram[54])
    state = {
        "ball_x": ball_x,
        "ball_y": ball_y,
        "ball_visible": ball_x != 0 and ball_y != 0,
        "player_y": int(ram[51]),
        "ball_dx": 0,
        "ball_dy": 0,
    }
    if previous_state and previous_state["ball_visible"] and state["ball_visible"]:
        state["ball_dx"] = state["ball_x"] - previous_state["ball_x"]
        state["ball_dy"] = state["ball_y"] - previous_state["ball_y"]
    return state


def make_policy(default_y, pred_x, follow_x, deadband, offset, follow_mode):
    def policy(state):
        if not state.get("ball_visible", False):
            return 1

        player_y = state["player_y"]
        ball_y = state["ball_y"]
        ball_x = state["ball_x"]
        ball_dx = state.get("ball_dx", 0)
        ball_dy = state.get("ball_dy", 0)

        target_y = default_y
        if ball_dx > 0:
            target_y = ball_y + ball_dy * max(0, pred_x - ball_x) / max(1, abs(ball_dx)) + offset
            while target_y < 42 or target_y > 208:
                if target_y < 42:
                    target_y = 84 - target_y
                elif target_y > 208:
                    target_y = 416 - target_y
        elif ball_x > follow_x:
            if follow_mode == 0:
                target_y = ball_y
            elif follow_mode == 1:
                target_y = (ball_y + default_y) / 2
            else:
                target_y = ball_y if abs(ball_y - player_y) > 18 else default_y

        if target_y < player_y - deadband:
            return 2
        if target_y > player_y + deadband:
            return 3
        return 0

    return policy


def eval_params(params, runs):
    env = gym.make("ALE/Pong-v5", obs_type="ram", render_mode=None)
    policy = make_policy(**params)
    margins = []
    try:
        for index in range(runs):
            seed = index
            env.action_space.seed(seed)
            ram, _ = env.reset(seed=seed)
            state = build_state(ram)
            player_score = 0
            opponent_score = 0
            for _ in range(100000):
                action = int(policy(state))
                ram, reward, terminated, truncated, _ = env.step(action)
                if reward > 0:
                    player_score += 1
                elif reward < 0:
                    opponent_score += 1
                if terminated or truncated or player_score >= 11 or opponent_score >= 11:
                    break
                state = build_state(ram, state)
            margins.append(player_score - opponent_score)
    finally:
        env.close()
    return sum(margins) / len(margins)


def main():
    candidates = []
    grid = itertools.product(
        [104, 108, 112, 116, 118, 120, 124, 128],
        [182, 184, 186, 188, 190, 192, 194, 196, 198],
        [120, 130, 140, 150, 160, 170, 180, 999],
        [3, 4, 5],
        [-4, -2, 0, 2, 4],
        [0, 1, 2],
    )
    for default_y, pred_x, follow_x, deadband, offset, follow_mode in grid:
        params = {
            "default_y": default_y,
            "pred_x": pred_x,
            "follow_x": follow_x,
            "deadband": deadband,
            "offset": offset,
            "follow_mode": follow_mode,
        }
        score = eval_params(params, runs=10)
        candidates.append((score, params))

    print("TOP20_BY_10")
    top = sorted(candidates, key=lambda item: item[0], reverse=True)[:20]
    for score, params in top:
        score30 = eval_params(params, runs=30)
        print(f"m30={score30:.2f} m10={score:.2f} {params}")


if __name__ == "__main__":
    main()

